import{b as t,c as n,_ as s,a as e}from"./chunks/fs55-1.Dvhuqj4q.js";import{_ as l,a as o,b as i,c as r}from"./chunks/fs47-1.M5gSViS3.js";import{_ as p,o as c,c as d,a4 as h}from"./chunks/framework.B0hSrcZ6.js";const g="/info/18-solo-s1.webp",u="/info/18-solo-s4.webp",k="/info/18-solo-s5.webp",w=JSON.parse('{"title":"第 18 章 案例：一人公司与 AI 团队","description":"本章解析一人公司依托单台云电脑构建 Grok Bot 团队的实操方案。从岗位定义到多角色编排，指导读者在共享边界内搭建交付流水线，平滑实现从单兵到多岗扩编。","frontmatter":{},"headers":[],"relativePath":"part2/18-solo.md","filePath":"part2/18-solo.md","lastUpdated":1792210948000}'),b={name:"part2/18-solo.md"};function m(f,a,y,x,B,_){return c(),d("div",null,[...a[0]||(a[0]=[h('<h1 id="第-18-章-案例-一人公司与-ai-团队" tabindex="-1">第 18 章 案例：一人公司与 AI 团队 <a class="header-anchor" href="#第-18-章-案例-一人公司与-ai-团队" aria-label="Permalink to &quot;第 18 章 案例：一人公司与 AI 团队&quot;">​</a></h1><p><strong>同一账号下的所有 Bot 共享同一台云端电脑</strong>，自带浏览器、文件系统与终端。</p><p>一口气新建十几个 Bot 并交出全部账号，容易踩坑。</p><ul><li>外部网页走错路径、静默覆盖数据</li><li>半夜频繁触发审批，让人疲于审核</li></ul><p>理顺岗位边界、凭据隔离与审批红线，就能<strong>从配置首个 AI 员工演进到管理 29 个 Agent</strong>。</p><h2 id="第一个-ai-员工-像招聘一样定义岗位与权限" tabindex="-1">第一个 AI 员工：像招聘一样定义岗位与权限 <a class="header-anchor" href="#第一个-ai-员工-像招聘一样定义岗位与权限" aria-label="Permalink to &quot;第一个 AI 员工：像招聘一样定义岗位与权限&quot;">​</a></h2><p><img src="'+g+`" alt="第一个 AI 员工：像招聘一样定义岗位与权限" width="1600" height="1013" decoding="async"></p><p>把 Bot 当作工具还是员工，取决于你是在写单次提示词，还是在确立岗位职责。单次提示词只管眼前的一项事务，窗口一关上下文就消失。岗位职责是一份固定的档案文件，它决定了这个 Bot 每天处理事务时的行为底线与思考模式。</p><h3 id="岗位定义与准入测试" tabindex="-1">岗位定义与准入测试 <a class="header-anchor" href="#岗位定义与准入测试" aria-label="Permalink to &quot;岗位定义与准入测试&quot;">​</a></h3><p><strong>先别给不可逆权限</strong>，从枯燥、高频且易撤销的杂事切入。</p><p>让 Bot 上手前，先跑两项准入测试提前排错。</p><ol><li><strong>一句话职责测试</strong>：一句讲清交付什么。塞入四五个无关动词等于一人干三人活，出错没法定位根因。</li><li><strong>纯文字推演（Trial in text）</strong>：耗时不到两分钟，先汇报步骤、预访网址与存疑判断。</li></ol><p>岗位描述拆成五个字段划清边界。</p><ul><li>Owns：交付固定产物。</li><li>Inputs：允许读取的渠道。</li><li>May：可自理的操作。</li><li>Must ask before：花钱或改配置等高危动作，<strong>必须等人工审批</strong>。</li><li>Done when：客观核对的验收清单。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先不要执行任何实际操作。请逐步向我推演你的完整执行方案：</span></span>
<span class="line"><span>1. 列出你准备依次打开的工具、网址与调用的插件。</span></span>
<span class="line"><span>2. 列出你在过程中需要做出的业务判断。</span></span>
<span class="line"><span>3. 标出你目前信息不足、存在疑虑或拿不准的决策点。</span></span>
<span class="line"><span>推演完毕后等待我的指令，严禁自行操作。</span></span></code></pre></div><details class="details custom-block"><summary>岗位定义与准入测试</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>岗位名称：收件箱管理员（Inbox Manager）</span></span>
<span class="line"><span>Owns：</span></span>
<span class="line"><span>每天上午梳理工作邮箱，归档垃圾邮件与订阅通讯，起草客户咨询的回复草稿，标出需要我决策的紧急邮件。</span></span>
<span class="line"><span>Inputs：</span></span>
<span class="line"><span>仅限于 Gmail 中收件箱的未读邮件与公司提供的常见问题回复模版。</span></span>
<span class="line"><span>May：</span></span>
<span class="line"><span>阅读邮件、按标签分类、打上处理标记、撰写回复草稿、归档无回复价值的宣传邮件。</span></span>
<span class="line"><span>Must ask before：</span></span>
<span class="line"><span>严禁直接点击发送任何邮件；严禁归档来自财务、法务或房东的邮件；如果邮件涉及转账、退款、重置密码或修改凭证，立即停下向我确认。</span></span>
<span class="line"><span>Done when：</span></span>
<span class="line"><span>工作日上午 9:00 前收件箱所有未读邮件分类完毕；生成的草稿不超过四句话，语气平实直接，不使用任何客套空话；所有待办事项单独列出截止日期。遇到不确定如何处理的邮件，保持未读并挂起询问，严禁自行猜测意图。</span></span></code></pre></div></details><p>岗位设定与临时提示词完全不同。</p><table tabindex="0"><thead><tr><th>维度</th><th>临时提示词</th><th>岗位设定</th></tr></thead><tbody><tr><td><strong>目标与形态</strong></td><td>单次对话，关注单次动作</td><td>长期配置，交付业务产物</td></tr><tr><td><strong>边界与权限</strong></td><td>口头交代易越权，出错重跑</td><td>可逆自理，不可逆等审批，硬设人闸</td></tr></tbody></table><h3 id="三次运行试用期与晋升阶梯" tabindex="-1">三次运行试用期与晋升阶梯 <a class="header-anchor" href="#三次运行试用期与晋升阶梯" aria-label="Permalink to &quot;三次运行试用期与晋升阶梯&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/distortgeekin/status/2105275395901726845" target="_blank" rel="noreferrer">Grok Bot: How to Hire Your First AI Employee (Full Guide)</a><br> 作者：<a href="https://x.com/distortgeekin" target="_blank" rel="noreferrer">distort @distortgeekin</a></p></blockquote><p><img src="`+t+'" alt="Grok Bot: How to Hire Your First AI Employee (Full Guide)" loading="lazy" decoding="async"></p><p><img src="'+n+`" alt="Grok Bot: How to Hire Your First AI Employee (Full Guide)" loading="lazy" decoding="async"></p><p>新 Bot 刚跑通，<strong>千万别直接放后台无人值守</strong>，先按 distort 的「三次运行法则」测试。</p><ol><li>第 1 次（全程旁观）：盯着屏幕看每步操作，记下误读指令、丢上下文和瞎猜的地方。</li><li>第 2 次（修复规则）：换同难度任务，不提醒旧错。重点看岗位规则与权限改动是否生效，不替它改结果。</li><li>第 3 次（放手实测）：全程不插手，只在审批或达到重试上限时介入，核验完成度、干预次数、耗时与额度。</li></ol><p><strong>通过三次测试后进入晋升阶梯</strong>，分五级权限。</p><table tabindex="0"><thead><tr><th style="text-align:left;">级别</th><th style="text-align:left;">机制</th><th style="text-align:left;">边界</th></tr></thead><tbody><tr><td style="text-align:left;">Level 0</td><td style="text-align:left;">仅观察</td><td style="text-align:left;">不改任何数据</td></tr><tr><td style="text-align:left;">Level 1</td><td style="text-align:left;">仅准备</td><td style="text-align:left;">搜索、摘要与排版等可逆工作</td></tr><tr><td style="text-align:left;">Level 2</td><td style="text-align:left;">人工审批</td><td style="text-align:left;">关键步骤挂起等待确认</td></tr><tr><td style="text-align:left;">Level 3</td><td style="text-align:left;">独立运行</td><td style="text-align:left;">定时或触发运行，定期产出证据链汇报</td></tr><tr><td style="text-align:left;">Level 4</td><td style="text-align:left;">多 Bot 协同</td><td style="text-align:left;">担任分发与质检节点</td></tr></tbody></table><p>升到下一级必须满足四项<strong>硬性指标</strong>。</p><ul><li>连续 5 次实跑无瑕疵</li><li>验证步骤全通过</li><li>无未解决的副作用</li><li>回滚机制验证可用</li></ul><p>实践参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/KGhnwWY0QiQrhgkKy2FcgECtnnc" target="_blank" rel="noreferrer">《Grok Bot: How to Hire Your First AI Employee (Full Guide)｜distort》</a> 与 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/PPKGwdkOkiGsxRkSInucbrNgnAg" target="_blank" rel="noreferrer">《Grok Bot Agents: how to automate your life in 10 Steps (Full-tutorial)｜Codez》</a>。</p><h2 id="从零到运转的公司-幕僚长与专职团队编排" tabindex="-1">从零到运转的公司：幕僚长与专职团队编排 <a class="header-anchor" href="#从零到运转的公司-幕僚长与专职团队编排" aria-label="Permalink to &quot;从零到运转的公司：幕僚长与专职团队编排&quot;">​</a></h2><p>一个人使用 Grok Bot 搭建完整业务运转体系时，最容易走入的死胡同就是给单个 Bot 堆积太多能力。一个既管销售线索、又管内容写作、还管对账和改代码的 Bot，其上下文窗口很快会被大量不相干的偏好填满，不仅容易混淆业务语境，还会加速额度损耗。</p><h3 id="幕僚长架构与部门拆分" tabindex="-1">幕僚长架构与部门拆分 <a class="header-anchor" href="#幕僚长架构与部门拆分" aria-label="Permalink to &quot;幕僚长架构与部门拆分&quot;">​</a></h3><p>搭团队先建幕僚长 Bot。你日常<strong>只跟幕僚长对接</strong>，由它拆解任务、调度专职岗位并汇总交付。</p><details class="details custom-block"><summary>幕僚长架构与部门拆分</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一人公司的幕僚长（Chief of Staff），也是我日常沟通的唯一入口。</span></span>
<span class="line"><span>你的核心职责：</span></span>
<span class="line"><span>1. 接收我的业务目标，拆解为明确的工作阶段，派发给对应的专职 Bot（调研、内容、代码、运维）。</span></span>
<span class="line"><span>2. 在群聊中调度各岗位接力，跟踪各任务交付状态。</span></span>
<span class="line"><span>3. 检查专职 Bot 提交的产物是否符合完成标准，核对数据来源与执行录屏。</span></span>
<span class="line"><span>4. 每天晚上汇总团队进展，用不超过五行文字向我汇报核心结果、阻塞问题与需要我决策的审批项。</span></span>
<span class="line"><span>行为底线：</span></span>
<span class="line"><span>若无任何新进展或异常，保持静默；严禁越权代替专职 Bot 编写业务交付内容；严禁绕过人工审批直接执行外发、扣款或修改生产环境。</span></span></code></pre></div></details><ul><li>调研 Bot：论断须注日期与网址，存疑主动标出，不强行编造。</li><li>内容 Bot：按模版排版，<strong>严禁直接对外发布</strong>。</li><li>销售 Bot：拜访邮件全存草稿箱，等人工核准再发。</li><li>技术 Bot：提 GitHub PR 必附测试通过截图。</li><li>财务 Bot：涉及资金调整必须单独列出待确认。</li></ul><details class="details custom-block"><summary>幕僚长架构与部门拆分</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>团队总体目标：</span></span>
<span class="line"><span>在两周内针对新上线的知识库产品，完成竞品定价调研，产出一份对比简报，并根据简报结构生成 3 篇官网更新草稿。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>协作规则：</span></span>
<span class="line"><span>1. 调研 Bot 先行检索 5 家竞品公开定价，生成包含引用网址的 Markdown 表格。</span></span>
<span class="line"><span>2. 调研完成后在群内移交给内容 Bot，内容 Bot 根据数据起草 3 篇文案，放入指定 Notion 页面。</span></span>
<span class="line"><span>3. 幕僚长全程跟进看板状态，若遇到数据缺失，要求责任 Bot 重新抓取或报错，不得擅自编造。</span></span>
<span class="line"><span>4. 全流程中所有涉及对外发布的操作全部挂起，等待我在看板中勾选通过。</span></span></code></pre></div></details><table tabindex="0"><thead><tr><th>架构</th><th>单兵全能</th><th>幕僚长流水线</th></tr></thead><tbody><tr><td>协作</td><td>记忆混杂难定位</td><td><strong>各岗独立记忆</strong>，精准定责</td></tr></tbody></table><h3 id="证据链审查与四周信任转移" tabindex="-1">证据链审查与四周信任转移 <a class="header-anchor" href="#证据链审查与四周信任转移" aria-label="Permalink to &quot;证据链审查与四周信任转移&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/N01ennn/status/2091534159088959967" target="_blank" rel="noreferrer">From Zero to a Running Company: The Grok Bot Agent Team Playbook</a><br> 作者：<a href="https://x.com/N01ennn" target="_blank" rel="noreferrer">NO1ennn @N01ennn</a></p></blockquote><p><img src="`+l+'" alt="From Zero to a Running Company: The Grok Bot Agent Team Playbook" loading="lazy" decoding="async"></p><p><img src="'+o+`" alt="From Zero to a Running Company: The Grok Bot Agent Team Playbook" loading="lazy" decoding="async"></p><p><strong>想放心合上电脑，前提是看到凭证（Show the tape）。</strong> Bot 交付必须带齐三项凭据。</p><ul><li>操作录屏或调用记录：展示完整网页轨迹或工具调用序列。</li><li>数据与数字的原始出处：禁止无来源引用。</li><li>报错跳过项与推测结论说明。</li></ul><p><strong>信任分四周逐步转移。</strong></p><ol><li>第 1 周（草稿阶段）：Bot 仅起草，人工通读并手动执行。</li><li>第 2 周（审批阶段）：Bot 跑到关键步停下，人工仅核对动作并审批。</li><li>第 3 周（异常上报阶段）：低风险事务自主跑，遇异常或越权才弹窗求助。</li><li>第 4 周（例程巡检阶段）：按例程完全自主运行，周末只看审计报告。</li></ol><p>相关实践参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/VGJmwyYrmiXLSSkdU3ackk1gnMd" target="_blank" rel="noreferrer">《From Zero to a Running Company: The Grok Bot Agent Team Playbook｜NO1ennn》</a> 与 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/MRhNwTEH8i0PrDkSp5uce2V7nKe" target="_blank" rel="noreferrer">《Grok Bot: How to Build Your First AI Team (Full Guide)》</a>。</p><h2 id="一人公司实战-单台云电脑的边界与独立运营" tabindex="-1">一人公司实战：单台云电脑的边界与独立运营 <a class="header-anchor" href="#一人公司实战-单台云电脑的边界与独立运营" aria-label="Permalink to &quot;一人公司实战：单台云电脑的边界与独立运营&quot;">​</a></h2><h3 id="物理边界" tabindex="-1">物理边界 <a class="header-anchor" href="#物理边界" aria-label="Permalink to &quot;物理边界&quot;">​</a></h3><p><strong>同账户所有 Bot 共享单台电脑</strong>，共用目录与会话。官方明确别把 Bot 当隔离边界，Prompt 防不住注入，误跑命令会泄露 Cookie 与 Session。</p><p>平时守住三条。</p><ul><li>不登主网银和核心仓库，不存机密网盘。</li><li>外部平台只用最小权限子账号。</li><li>外部登录走 Handoff，人工输密码，Bot 只继承 Session。</li></ul><h3 id="无-api-系统自动化" tabindex="-1">无 API 系统自动化 <a class="header-anchor" href="#无-api-系统自动化" aria-label="Permalink to &quot;无 API 系统自动化&quot;">​</a></h3><p><strong>无 API 系统靠计算机能力点击填表</strong>，四类工作适合先交接。</p><ul><li>获客调研：扫社群目录并起草邮件。</li><li>履约跟进：核对缺货并跟进延误运单。</li><li>内容排期：文案填进草稿箱。</li><li>代码维护：排查独立站报错并出补丁。</li></ul><details class="details custom-block"><summary>无 API 系统自动化</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>岗位名称：供应链履约跟踪员（Supplier Logistics Bot）</span></span>
<span class="line"><span>Owns：</span></span>
<span class="line"><span>每天上午 10:00 登录供应商门户，核对昨天未发货订单状态，提取物流单号，更新至运营表格。</span></span>
<span class="line"><span>Inputs：</span></span>
<span class="line"><span>供应商订货后台会话、本地待处理订单表格。</span></span>
<span class="line"><span>May：</span></span>
<span class="line"><span>在供应商后台查询订单状态、下载发货清单 CSV、更新本地表格对应列的运单号与发货时间。</span></span>
<span class="line"><span>Must ask before：</span></span>
<span class="line"><span>严禁点击「重新下单」或「取消订单」；严禁修改收货地址；若供应商后台提示账户欠款或商品缺货，停止处理并立即向我报警。</span></span>
<span class="line"><span>Done when：</span></span>
<span class="line"><span>所有处理过的运单在表格中均标注状态与回填时间；遇到后台页面改版导致按钮无法识别时，截取当前屏幕报错并退出，不得盲目重试。</span></span></code></pre></div></details><h3 id="门槛与评分" tabindex="-1">门槛与评分 <a class="header-anchor" href="#门槛与评分" aria-label="Permalink to &quot;门槛与评分&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/zerqfer/status/2093299037705236540" target="_blank" rel="noreferrer">One-Computer Company: A Real Playbook For Running Solo On Grok Bot</a><br> 作者：<a href="https://x.com/zerqfer" target="_blank" rel="noreferrer">ZER @zerqfer</a></p></blockquote><p><strong>人工审查稳定降至每天 15 分钟内</strong>才能加新 Bot，避免放大负担。每月填一次评分卡防静默衰退。</p><details class="details custom-block"><summary>门槛与评分</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bot 月度运行评分卡</span></span>
<span class="line"><span>评估周期：2026 年 10 月</span></span>
<span class="line"><span>岗位名称：[例如：订单跟进助理]</span></span>
<span class="line"><span>1. 实际工时节省：本月相比纯手工操作，实际节省了约多少小时？</span></span>
<span class="line"><span>2. 人工介入程度：产出草稿中，需要人工手动大幅修改的比例是多少（低于 10% 算达标）？</span></span>
<span class="line"><span>3. 信任度变化趋势：对该岗位的自主执行信任度处于上升、持平还是下滑？</span></span>
<span class="line"><span>4. 异常与回滚记录：本月出现过几次页面识别错误或越权报警？</span></span>
<span class="line"><span>5. 处置结论：[保留继续运行 / 降级为人工审批执行 / 彻底停用删除]</span></span></code></pre></div></details><p>参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/VcevwDlGGimAvjkEGGPceItanNg" target="_blank" rel="noreferrer">《One-Computer Company: A Real Playbook For Running Solo On Grok Bot｜ZER》</a>。</p><h2 id="ai-agency-交付体系-月交付流水线与质检人闸" tabindex="-1">AI Agency 交付体系：月交付流水线与质检人闸 <a class="header-anchor" href="#ai-agency-交付体系-月交付流水线与质检人闸" aria-label="Permalink to &quot;AI Agency 交付体系：月交付流水线与质检人闸&quot;">​</a></h2><p><img src="`+u+'" alt="AI Agency 交付体系：月交付流水线与质检人闸" width="1600" height="1013" loading="lazy" decoding="async"></p><p>对于面向多客户交付的 AI 代理机构（AI Agency），核心难点在于多客户并发时的质量稳定与额度成本控制。</p><p>社区作者 maestro 分享了单人服务 5 家 Retainer 客户、实现月度业务运转的体系架构（社区作者 maestro 自述月营 1.8 万美元、服务 5 家客户，未核）。</p><h3 id="业务菜单的「三项准入测试」" tabindex="-1">业务菜单的「三项准入测试」 <a class="header-anchor" href="#业务菜单的「三项准入测试」" aria-label="Permalink to &quot;业务菜单的「三项准入测试」&quot;">​</a></h3><p>别接全定制沦为手工外包，<strong>业务进自动交付菜单得过三关</strong>。</p><ol><li>Brief 能写成结构化清单。</li><li>交付物有第三方客观验收标准。</li><li><strong>此前纯手工交付至少 10 次</strong>。没做满 10 次摸不清红线，交给智能体只会产出废话。</li></ol><p>达标业务包含 500K 上下文比对 40 篇资料做研报、按声音样本（Voice File）批量写稿，或搭建看板与轻量抓取工具。</p><h3 id="模型路由与-19-5-万-token-计费悬崖拦截" tabindex="-1">模型路由与 19.5 万 Token 计费悬崖拦截 <a class="header-anchor" href="#模型路由与-19-5-万-token-计费悬崖拦截" aria-label="Permalink to &quot;模型路由与 19.5 万 Token 计费悬崖拦截&quot;">​</a></h3><p>模型按活分配，别全上旗舰。</p><ul><li>Grok 4.1 Fast：2M 上下文，跑清洗初筛。</li><li>Grok Build 0.1：负责 80% 开发物料。</li><li>Grok 4.6：500K，跑长程 Agent 与推理。</li></ul><p><strong>输入超 200,000 Token 费率直接翻倍</strong>。网关要<strong>硬编码 195,000 Token 阈值</strong>，超限报错截断或剪枝。</p><h3 id="独立只读审核者与三次重试人闸" tabindex="-1">独立只读审核者与三次重试人闸 <a class="header-anchor" href="#独立只读审核者与三次重试人闸" aria-label="Permalink to &quot;独立只读审核者与三次重试人闸&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/maestrooth/status/2092658066714177657" target="_blank" rel="noreferrer">How to Build an $18K/Month AI Agency on Grok (Exact Setup Inside)</a><br> 作者：<a href="https://x.com/maestrooth" target="_blank" rel="noreferrer">maestro @maestrooth</a></p></blockquote><p><img src="'+i+'" alt="How to Build an $18K/Month AI Agency on Grok (Exact Setup Inside)" loading="lazy" decoding="async"></p><p><img src="'+r+`" alt="How to Build an $18K/Month AI Agency on Grok (Exact Setup Inside)" loading="lazy" decoding="async"></p><p>生产 Bot 审自己的产物会有自洽倾向，容易掩盖提示词失效。<strong>审核必须切成独立的只读回路</strong>。</p><ul><li>独立上下文：只输入原始 Brief、客户规范和产物，不给中间推理。</li><li>严格只读：<strong>发现缺陷只报 FAIL 绝不代笔</strong>，防止私自修补掩盖问题。</li><li>对抗挑刺：专抓硬伤，没有资料支持的数字一律判挂。</li></ul><details class="details custom-block"><summary>独立只读审核者与三次重试人闸</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 独立审查者审核准则（reviewer.md）</span></span>
<span class="line"><span>你是一名独立质量审查员，负责评估一份并非由你生产的交付产物。</span></span>
<span class="line"><span>你的唯一任务是找出交付物不符合客户要求的地方。你绝不需要去赞美它的优点。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输入物料：</span></span>
<span class="line"><span>原始需求 Brief、服务核对清单、客户品牌声音规范文件、最终交付草稿。</span></span>
<span class="line"><span>你未被提供、也严禁索取生产 Bot 的思考草稿。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>审查规则（按顺序严格执行）：</span></span>
<span class="line"><span>1. 逐条核对需求 Brief 中的清单项。指出任何未被完全覆盖的要点。</span></span>
<span class="line"><span>2. 检查全文，严禁残留任何占位符文字、TODO 标记或括号说明文本。</span></span>
<span class="line"><span>3. 全文中的每一个具体数字、引文、统计百分比与人名，必须能在客户资料库中找到对应出处。发现任何未注明来源的数字，必须直接判定为 FAIL。</span></span>
<span class="line"><span>4. 语言风格是否符合客户过往已批准作品的语气标准。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出格式：</span></span>
<span class="line"><span>第一行必须且只能输出一个词：PASS 或 FAIL。</span></span>
<span class="line"><span>如果判定为 FAIL，按以下格式列出所有缺陷：[清单条款] - [出现位置] - [具体问题及修正要求]。第一行后严禁输出任何空洞的总结段落。</span></span>
<span class="line"><span>若因上下文缺少凭据导致无法核验某一项，直接判定为 FAIL。</span></span></code></pre></div></details><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单任务自动化生产循环规则：</span></span>
<span class="line"><span>1. 生产 Bot 基于需求与声音规范生成第 1 版草稿。</span></span>
<span class="line"><span>2. 独立审核 Bot 执行审查。若返回 PASS，记录日志并进入待交付队列。</span></span>
<span class="line"><span>3. 若返回 FAIL，系统将审查不通过的具体原因拼接入下一轮 Brief，由生产 Bot 进行针对性修复重试。</span></span>
<span class="line"><span>4. 重试上限（MAX_ATTEMPTS）严格设定为 3 次。</span></span>
<span class="line"><span>5. 若连续 3 次均无法通过审查，系统立即终止自动重试，触发报警将原始 Brief、草稿与审查报错完整推送到人工桌面由人工兜底接管。</span></span></code></pre></div><p><strong>交接重试最多 3 次</strong>，防止死循环刷出高额 Token 账单。机器试了三次仍不达标，说明需求冲突，必须由人工介入判定。</p><p>参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/MtKDwMe0FiNf4wkxwj7cgnnAndf" target="_blank" rel="noreferrer">《How to Build an $18K/Month AI Agency on Grok (Exact Setup Inside)｜maestro》</a>。</p><h2 id="_29-个-agent-的实战-如何从单兵平滑扩编到军团" tabindex="-1">29 个 Agent 的实战：如何从单兵平滑扩编到军团 <a class="header-anchor" href="#_29-个-agent-的实战-如何从单兵平滑扩编到军团" aria-label="Permalink to &quot;29 个 Agent 的实战：如何从单兵平滑扩编到军团&quot;">​</a></h2><p><img src="`+k+`" alt="29 个 Agent 的实战：如何从单兵平滑扩编到军团" width="1600" height="1013" loading="lazy" decoding="async"></p><p>当你熟悉了单个员工的配置与双 Bot 的质检闭环，业务需求自然会推动你扩建团队。</p><p>社区作者 Melvin Vivas 记录了自己如何一步步将 Grok Bot 扩充至 29 个专职智能体的完整实践（社区作者 Melvin Vivas 自述拥有 29 个 Bot，未核）。</p><h3 id="_29-个-agent-的职能布局与渐进演进" tabindex="-1">29 个 Agent 的职能布局与渐进演进 <a class="header-anchor" href="#_29-个-agent-的职能布局与渐进演进" aria-label="Permalink to &quot;29 个 Agent 的职能布局与渐进演进&quot;">​</a></h3><p><strong>这 29 个 Bot 全是按需长出来的</strong>：平时遇到重复事务就建专职角色，角色多了再由幕僚长 Emma 统管。业务分为七大板块：</p><ul><li>调度中枢：Emma 负责统管全局与分发任务。</li><li>技术研发：CTO 管架构；<strong>Coder 调动 Cursor 自动编写代码提 PR 并修复报错</strong>，全程不用开本地编辑器。</li><li>前沿调研：全天扫描 X 平台开源动态并出简报。</li><li>内容矩阵：负责各渠道文案创作与复盘。</li><li>商务拓展：挖掘商机与合作线索。</li><li>运营安全：负责邮件、备份与安全审查。</li><li>个人成长：处理打卡、行情追踪与决策论证。</li></ul><h3 id="多-agent-协同流水线-以技术原型到内容转换为例" tabindex="-1">多 Agent 协同流水线：以技术原型到内容转换为例 <a class="header-anchor" href="#多-agent-协同流水线-以技术原型到内容转换为例" aria-label="Permalink to &quot;多 Agent 协同流水线：以技术原型到内容转换为例&quot;">​</a></h3><p>各 Bot 靠共享云电脑和会话引用接力。</p><details class="details custom-block"><summary>多 Agent 协同流水线：以技术原型到内容转换为例</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>端到端跨团队协同案例：</span></span>
<span class="line"><span>1. 【情报捕获】：X 调研员监控到某大模型最新发布，抓取官方文档与代码仓库地址，整理为技术要点。</span></span>
<span class="line"><span>2. 【任务调度】：幕僚长 Emma 捕获该报告，根据设定规则判定该模型具备测试价值，自动将任务下发给技术团队。</span></span>
<span class="line"><span>3. 【工程交付】：编码员 Coder 接收技术说明，调起 Cursor Cloud coding agent 在云端编写 Google Colab 演示笔记本，推送到 GitHub 仓库并自动创建 Pull Request。</span></span>
<span class="line"><span>4. 【排错闭环】：执行测试出现依赖包版本冲突，终端 Traceback 自动返回 Coder，Coder 修复代码再次提交 PR 通过测试。</span></span>
<span class="line"><span>5. 【内容物料转译】：PR 合并后，Emma 将成功代码仓库与技术参数推送给内容创作团队，YouTube 脚本助手与 X 内容经理在半小时内完成多平台发布草稿，存入指定待审目录。</span></span>
<span class="line"><span>6. 【人闸闭环】：创始人全程不介入代码编写与格式排版，仅在最后核验 Colab 实际运行效果，并点击确认对外发布推文。</span></span></code></pre></div></details><p><strong>改动不用挨个点开 29 个窗口</strong>，总管广播一条指令几秒就能同步。</p><h3 id="角色拆分的五大信号与自动化七步法" tabindex="-1">角色拆分的五大信号与自动化七步法 <a class="header-anchor" href="#角色拆分的五大信号与自动化七步法" aria-label="Permalink to &quot;角色拆分的五大信号与自动化七步法&quot;">​</a></h3><p>考核目标、调用工具、工作风格、审批边界（草稿与对外沟通绝不能混）或调度周期不同时，必须<strong>拆分独立 Bot</strong>。</p><ol><li>Bot Description 写清目标、数据源、格式与停机边界。</li><li>挑受控真实任务单次运行。</li><li>人工调优到免检。</li><li>沉淀为复用 Skill。</li><li>换新数据复测泛化。</li><li><strong>定好重试上限与缺失报警，才开 Routine</strong>。</li><li>发信、付款或改动，强绑 Require Approval 人闸。</li></ol><table tabindex="0"><thead><tr><th style="text-align:left;">阶段</th><th style="text-align:left;">规模</th><th style="text-align:left;">架构与瓶颈</th></tr></thead><tbody><tr><td style="text-align:left;">1 单兵</td><td style="text-align:left;">1 Bot</td><td style="text-align:left;">全量人闸验证闭环；需时刻盯盘</td></tr><tr><td style="text-align:left;">2 小组</td><td style="text-align:left;">2-3 Bot</td><td style="text-align:left;">生产与审核分离；日维护压进 15 分钟</td></tr><tr><td style="text-align:left;">3 幕僚长</td><td style="text-align:left;">4-6 Bot</td><td style="text-align:left;">分发与看板；<strong>杜绝幕僚长干杂活</strong></td></tr><tr><td style="text-align:left;">4 军团</td><td style="text-align:left;">10-30 Bot</td><td style="text-align:left;">多线 standup；定期修剪无效例程</td></tr></tbody></table><h3 id="看板系统与晨会机制" tabindex="-1">看板系统与晨会机制 <a class="header-anchor" href="#看板系统与晨会机制" aria-label="Permalink to &quot;看板系统与晨会机制&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/melvindvivas/status/2109480575421808962" target="_blank" rel="noreferrer">How I use Grok Bot: My team of 29 AI agents</a><br> 作者：<a href="https://x.com/melvindvivas" target="_blank" rel="noreferrer">Melvin Vivas @melvindvivas</a></p></blockquote><p>Bot 超过 5 个就别用多聊天窗口了，根本看不过来。<strong>多 Bot 协同主要靠看板和定时巡检两件事</strong>：</p><ul><li><p><strong>共享状态看板</strong>：任务别散在聊天记录里，统一收拢到 Notion 或数据库看板，定好五种状态：<code>Todo</code>、<code>Working</code>、<code>Blocked</code>、<code>Ready for Review</code>、<code>Done</code>。</p><p>Bot 遇到未知报错或缺权限直接改标 <code>Blocked</code> 并呼叫人工，平时看卡片流转就行。</p></li><li><p><strong>定时巡检与对账</strong>：单 Bot 最多配 50 个 Routine，最高每 5 分钟跑一次。</p><p><strong>凌晨 3:00 自动体检代码死链与包体积，5:00 由总管 Bot（如 Jenny）逐个核对专职 Bot 的 Playbook</strong>，能有效防止模型久了遗忘。</p></li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>全体专职 Bot，开始进行本周团队回顾审计。请各岗位汇报：</span></span>
<span class="line"><span>1. 本周你实际执行了多少次任务，其中失败或异常的中断有多少次？</span></span>
<span class="line"><span>2. 在执行过程中，有哪些步骤存在推测行为、跳过行为或由于数据缺失强行拼凑的情况？</span></span>
<span class="line"><span>3. 有哪些挂起的审批事项我一直没有回应？有哪些生成的物料我从来没有打开查看过？</span></span>
<span class="line"><span>4. 请指出：在当前的工作流中，你发现哪两个 Bot 存在职责重叠或重复工作？</span></span>
<span class="line"><span>5. 给出客观建议：为了节省整体用量额度，我们下周最应该裁撤哪一个无效的 Routine 或岗位？</span></span></code></pre></div><p>相关实践参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/YBjswa1rnivPkjk5BpscN6mcnDh" target="_blank" rel="noreferrer">《How I use Grok Bot: My team of 29 AI agents》</a>、<a href="https://jcng5q8n0f3z.feishu.cn/wiki/LSfqwAew5i4h3mkuQT9cgw3jn54" target="_blank" rel="noreferrer">《GrokBot Agents: build a team that works for you 24/7 in 10 steps (Full-Course)｜Movez》</a> 与 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/MRhNwTEH8i0PrDkSp5uce2V7nKe" target="_blank" rel="noreferrer">《Grok Bot: How to Build Your First AI Team (Full Guide)》</a>。</p><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><h3 id="权限与审批" tabindex="-1">权限与审批 <a class="header-anchor" href="#权限与审批" aria-label="Permalink to &quot;权限与审批&quot;">​</a></h3><ol><li>共享云电脑共用 Session 无隔离，<strong>绝不要登录主账户和敏感系统</strong>。</li><li>Require Approval 只能拦未执行操作，无法撤销破坏，<strong>高危动作首次就设死人闸</strong>。</li><li>审批约 10 分钟不理会失效（Lapse），夜间<strong>必须配 Allow rule 白名单或停在草稿</strong>。</li></ol><h3 id="成本与架构" tabindex="-1">成本与架构 <a class="header-anchor" href="#成本与架构" aria-label="Permalink to &quot;成本与架构&quot;">​</a></h3><ol start="4"><li>输入超 20 万（200,000）Token 单价翻倍：<strong>路由层要设 195,000 Token 硬拦截与剪枝</strong>。</li><li>别搞单 Bot 揽全活或克隆 5 个通用 Bot，<strong>分工不清只会污染上下文并浪费额度</strong>。</li><li>别设 5 分钟轮询或监听全消息，<strong>缺 No-data policy 时断网容易瞎编数据耗尽额度</strong>。</li></ol><h3 id="规则与交接" tabindex="-1">规则与交接 <a class="header-anchor" href="#规则与交接" aria-label="Permalink to &quot;规则与交接&quot;">​</a></h3><ol start="7"><li>聊天框叮嘱刷新就失效，<strong>跨任务纪律必须写在设置界面的 Description</strong>。</li><li>跨 Bot 别搬运全部记录，<strong>交接包只留目标与交付物路径，加上结论和下一步要求</strong>。</li></ol><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><ol><li><strong>查凭据</strong>：清掉 Plugins 和浏览器的银行与主凭据，改用子账号或 Session，<strong>聊天记录绝不存明文密码</strong>。</li><li><strong>验岗位</strong>：Bot 须包含 Owns/Inputs/May/Must ask before/Done when，末尾加反漂移声明，<strong>缺数据立即报错、严禁编造</strong>。</li><li><strong>测人闸</strong>：发扣款或删除指令，必须 <strong>100% 触发 Require Approval 挂起</strong>。</li><li><strong>抗审核</strong>：喂假数据草稿，质检 Bot 须 <strong>第一行返回 FAIL</strong> 且不擅改；连续失败 3 次停机报警。</li><li><strong>稳例程</strong>：看板状态实时流转，开启前点 Test run 跑通，<strong>定时任务不依赖超 10 分钟夜间审批</strong>。</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><h3 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to &quot;官方文档&quot;">​</a></h3><ul><li><a href="https://cursor.com/cn/docs/grok-bot/work.md" target="_blank" rel="noreferrer">在 Grok Bot 中组织业务与工作（docs_grok-bot_work.md）</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/teams.md" target="_blank" rel="noreferrer">团队版 Bot 协作与权限管理（docs_grok-bot_teams.md）</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/security.md" target="_blank" rel="noreferrer">Grok Bot 安全架构与执行环境（docs_grok-bot_security.md）</a></li><li><a href="https://cursor.com/cn/help/grok-bot/plans.md" target="_blank" rel="noreferrer">方案、额度与计费说明（help_grok-bot_plans.md）</a></li><li><a href="https://cursor.com/cn/help/grok-bot/routines.md" target="_blank" rel="noreferrer">配置定时任务与触发例程（help_grok-bot_routines.md）</a></li><li><a href="https://cursor.com/cn/help/grok-bot/connect-plugins.md" target="_blank" rel="noreferrer">连接外部应用与官方插件（help_grok-bot_connect-plugins.md）</a></li></ul><h3 id="社区实战来源" tabindex="-1">社区实战来源 <a class="header-anchor" href="#社区实战来源" aria-label="Permalink to &quot;社区实战来源&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/0xMovez/status/2100261918896169259" target="_blank" rel="noreferrer">GrokBot Agents: build a team that works for you 24/7 in 10 steps (Full-Course)</a><br> 作者：<a href="https://x.com/0xMovez" target="_blank" rel="noreferrer">Movez @0xMovez</a></p></blockquote><p><img src="`+s+'" alt="GrokBot Agents: build a team that works for you 24/7 in 10 steps (Full-Course)" loading="lazy" decoding="async"></p><p><img src="'+e+'" alt="GrokBot Agents: build a team that works for you 24/7 in 10 steps (Full-Course)" loading="lazy" decoding="async"></p><ul><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/VGJmwyYrmiXLSSkdU3ackk1gnMd" target="_blank" rel="noreferrer">《From Zero to a Running Company: The Grok Bot Agent Team Playbook｜NO1ennn》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/MtKDwMe0FiNf4wkxwj7cgnnAndf" target="_blank" rel="noreferrer">《How to Build an $18K/Month AI Agency on Grok (Exact Setup Inside)｜maestro》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/VcevwDlGGimAvjkEGGPceItanNg" target="_blank" rel="noreferrer">《One-Computer Company: A Real Playbook For Running Solo On Grok Bot｜ZER》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/LSfqwAew5i4h3mkuQT9cgw3jn54" target="_blank" rel="noreferrer">《GrokBot Agents: build a team that works for you 24/7 in 10 steps (Full-Course)｜Movez》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/KGhnwWY0QiQrhgkKy2FcgECtnnc" target="_blank" rel="noreferrer">《Grok Bot: How to Hire Your First AI Employee (Full Guide)｜distort》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/MRhNwTEH8i0PrDkSp5uce2V7nKe" target="_blank" rel="noreferrer">《Grok Bot: How to Build Your First AI Team (Full Guide)》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/YBjswa1rnivPkjk5BpscN6mcnDh" target="_blank" rel="noreferrer">《How I use Grok Bot: My team of 29 AI agents》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/PPKGwdkOkiGsxRkSInucbrNgnAg" target="_blank" rel="noreferrer">《Grok Bot Agents: how to automate your life in 10 Steps (Full-tutorial)｜Codez》</a></li></ul>',120)])])}const G=p(b,[["render",m]]);export{w as __pageData,G as default};
